const MI = { hi: 2, en: 3, bn: 4 };
const CSS = '<style>.hc-v{padding:12px 0;border-bottom:1px solid var(--line)}.hc-l{font-size:1.3rem;font-weight:700;line-height:1.75;margin:0}.hc-r{font-style:italic;margin:.3rem 0}.hc-m{margin:.3rem 0;color:var(--muted)}.hc-tools{display:flex;flex-wrap:wrap;gap:10px;align-items:center;margin:12px 0}.hc-big .hc-l{font-size:1.75rem}.hc-nom .hc-m{display:none}.mt-src{color:var(--muted);font-size:.95rem}.jp{display:flex;flex-direction:column;align-items:center;gap:10px;padding:16px;border:1px solid var(--line);border-radius:18px;margin:14px 0}.jp button.big{width:170px;height:170px;border-radius:50%;border:0;font-size:1.25rem;font-weight:800;color:#fff;background:radial-gradient(circle at 35% 30%,#ff922b,#e8590c);box-shadow:0 8px 24px rgba(232,89,12,.35);cursor:pointer;touch-action:manipulation}.jp button.big:active{transform:scale(.97)}.jp .n{font-size:2.4rem;font-weight:800;font-variant-numeric:tabular-nums}.jp progress{width:100%;max-width:320px}.mt-list{list-style:none;padding:0;display:grid;gap:10px}.mt-list a{display:block;padding:12px 14px;border:1px solid var(--line);border-radius:12px;text-decoration:none}.mt-list small{display:block;color:var(--muted)}@media print{header,footer,.no-print,.ad{display:none!important}}</style>';

export function buildMantras(L, { page, write, P, esc, T, breadcrumbLd, LANGS }) {
  const code = L.code, U = UI[code]; if (!U) return;
  const langs = LANGS.filter((l) => UI[l.code]), hub = '/mantra/';
  const faqLd = (faq) => ({ '@context': 'https://schema.org', '@type': 'FAQPage', mainEntity: faq.map(([q, a]) => ({ '@type': 'Question', name: q, acceptedAnswer: { '@type': 'Answer', text: a } })) });
  const faqHtml = (faq) => faq.map(([q, a]) => `<h3>${esc(q)}</h3><p>${esc(a)}</p>`).join('');
  const short = (m) => m.name[code].split(' (')[0];
  const crumbs = (x) => `<p class="crumbs no-print"><a href="${P(L, '/')}">${esc(T.nav.home)}</a> › ${x}</p>`;
  write(L, hub, page(L, {
    path: hub, title: U.hubT, description: U.hubD, langs, jsonLd: [breadcrumbLd(L, [[T.nav.home, '/'], [U.hub, hub]]), faqLd(U.hubFaq)],
    body: `${CSS}<div class="wrap narrow article">${crumbs(esc(U.hub))}<h1>${esc(U.hubH1)}</h1><p class="lead">${esc(U.hubLead)}</p>
<ul class="mt-list">${M.map((m) => `<li><a href="${P(L, `${hub}${m.slug}/`)}"><b>${m.emoji} ${esc(m.name[code])}</b><small>${esc(m.src[code])}</small></a></li>`).join('')}</ul>
<div class="ad no-print" aria-hidden="true"></div>${U.hubAbout.map((p) => `<p>${esc(p)}</p>`).join('')}
<h2>${esc(U.howH)}</h2><ul>${U.how.map((p) => `<li>${esc(p)}</li>`).join('')}</ul>
<h2>${esc(U.faqH)}</h2>${faqHtml(U.hubFaq)}
<p class="chips no-print"><a class="tag" href="${P(L, '/aarti/')}">🪔 ${esc(U.aarti)}</a> <a class="tag" href="${P(L, '/hanuman-chalisa/')}">🙏 ${esc(U.chalisa)}</a></p></div>`,
  }));
  M.forEach((m) => {
    const path = `${hub}${m.slug}/`, mi = MI[code];
    const verses = m.lines.map((v) => `<div class="hc-v"><p class="hc-l">${esc(code === 'bn' ? toBn(v[0]) : v[0]).replace(/\n/g, '<br>')}</p>${code === 'en' ? `<p class="hc-r">${esc(v[1]).replace(/\n/g, '<br>')}</p>` : ''}<p class="hc-m">${esc(v[mi])}</p></div>`).join('\n');
    const key = `jp-${m.slug}`;
    const jaap = `<div class="jp no-print" id="jp"><h2 style="margin:0">${esc(U.jaapH)}</h2><p style="margin:0;text-align:center">${esc(U.jaapL)}</p><div class="n"><span id="jp-n">0</span> / 108</div><progress id="jp-p" max="108" value="0"></progress><button class="big" type="button" id="jp-b">${esc(U.tap)}</button><div><b id="jp-m">0</b> ${esc(U.malas)}</div><button class="btn btn-ghost" type="button" id="jp-r">${esc(U.reset)}</button></div>
<script>(function(){var K='${key}',n=0,ml=0;try{var s=JSON.parse(localStorage.getItem(K)||'{}');n=s.n||0;ml=s.m||0;}catch(e){}
function show(){document.getElementById('jp-n').textContent=n;document.getElementById('jp-p').value=n;document.getElementById('jp-m').textContent=ml;try{localStorage.setItem(K,JSON.stringify({n:n,m:ml}));}catch(e){}}
document.getElementById('jp-b').onclick=function(){n++;if(n>=108){n=0;ml++;if(navigator.vibrate)navigator.vibrate([80,60,80]);}else if(navigator.vibrate)navigator.vibrate(15);show();};
document.getElementById('jp-r').onclick=function(){if(confirm(${JSON.stringify(U.confirmReset)})){n=0;ml=0;show();}};
var b=document.getElementById('mt-body');document.getElementById('mt-mean').onchange=function(){b.classList.toggle('hc-nom',!this.checked);};document.getElementById('mt-big').onchange=function(){b.classList.toggle('hc-big',this.checked);};show();})();</script>`;
    const others = M.filter((o) => o !== m).map((o) => `<a class="tag" href="${P(L, `${hub}${o.slug}/`)}">${o.emoji} ${esc(short(o))}</a>`).join(' ');
    write(L, path, page(L, {
      path, title: U.t(m), description: U.d(m), langs, jsonLd: [breadcrumbLd(L, [[T.nav.home, '/'], [U.hub, hub], [short(m), path]]), faqLd(m.faq[code])],
      body: `${CSS}<div class="wrap narrow article">${crumbs(`<a href="${P(L, hub)}">${esc(U.hub)}</a> › ${esc(short(m))}`)}
<h1>${m.emoji} ${esc(m.name[code])}</h1><p class="mt-src">${esc(U.srcL)}: ${esc(m.src[code])}</p>
<div class="hc-tools no-print"><label><input type="checkbox" id="mt-mean" checked> ${esc(U.mean)}</label><label><input type="checkbox" id="mt-big"> ${esc(U.big)}</label></div>
<div id="mt-body">${verses}</div>
${jaap}
<div class="ad no-print" aria-hidden="true"></div>
<h2>${esc(U.aboutH)}</h2>${m.about[code].map((p) => `<p>${esc(p)}</p>`).join('')}
<h2>${esc(U.howH)}</h2><ul>${U.how.map((p) => `<li>${esc(p)}</li>`).join('')}</ul>
<h2>${esc(U.faqH)}</h2>${faqHtml(m.faq[code])}
<h2 class="no-print">${esc(U.more)}</h2><p class="chips no-print">${others} <a class="tag" href="${P(L, '/aarti/')}">🪔 ${esc(U.aarti)}</a> <a class="tag" href="${P(L, hub)}">📿 ${esc(U.hub)}</a></p></div>`,
    }));
  });
}
export const MANTRA_LIST = M.map((m) => ({ slug: m.slug, en: m.name.en, src: m.src.en }));
export const OG_CARDS = [{ file: 'mantra', path: '/mantra/', emoji: '📿', deco: '🕉🪔🌺', title: 'मंत्र — अर्थ सहित' }, ...M.map((m) => ({ file: `mantra-${m.slug}`, path: `/mantra/${m.slug}/`, emoji: m.emoji, deco: '📿🪔🌺', title: m.name.hi.split(' (')[0] }))];
